// ATF-CP-UI-03: Product Detail and Cart UI
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#catalog');
await screen.findByText('Product Catalog', { exact: false }, { timeout: 15000 });
await sn_atf.delay(2000);
var viewBtns = await screen.findAllByText('View Details', { exact: true });
await user.click(viewBtns[0]);
var backBtn = await screen.findByText(/Back to Catalog/i, {}, { timeout: 10000 });
expect(backBtn).toBeVisible();
var qtyInput = await screen.findBySelector('input.qty-input');
await user.clear(qtyInput);
await user.type(qtyInput, '3');
await user.tab();
await sn_atf.delay(500);
var uomEl = await screen.queryByText('UOM');
if (uomEl) expect(uomEl).toBeVisible();
var lineTotalEl = await screen.queryByText('Line Total');
if (lineTotalEl) expect(lineTotalEl).toBeVisible();
var addBtn = await screen.findByText('Add to Cart', { exact: true });
await user.click(addBtn);
var addedMsg = await screen.findByText(/Added to Cart/i, {}, { timeout: 5000 });
expect(addedMsg).toBeVisible();
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#cart');
var cartHeading = await screen.findByText('Shopping Cart', { exact: false }, { timeout: 10000 });
expect(cartHeading).toBeVisible();
var cartItems = await screen.queryAllBySelector('.cart-item');
expect(cartItems.length).toBeGreaterThan(0);
